#!/bin/sh
# Builds the page as static files — no server needed to hear a poem:
#
#   index.html           the page, sending its requests to the compiler beside it
#   strudel-globals.mjs  the module its import map points Strudel's own imports at
#   prosody.js           the compiler's bindings, generated by `wasm-bindgen`
#   prosody_bg.wasm      the whole compiler (`crates/prosody-wasm`)
#
#   ./scripts/build-site.sh              into target/site
#   ./scripts/build-site.sh DIR          into DIR
#
# Serve the directory with any static file server (`python3 -m http.server -d target/site`);
# opening index.html from disk does not work, because browsers refuse to fetch beside a file://.
set -eu

here=$(dirname "$0")
cd "$here/.."
dir="${1:-target/site}"

# The C parser's objects are wasm, and macOS's `ar` cannot index them — the link then fails with
# every `ts_*` symbol undefined. The toolchain's own `llvm-ar` can (rust-toolchain.toml asks for
# `llvm-tools`).
host=$(rustc -vV | sed -n 's/^host: //p')
llvm_ar="$(rustc --print sysroot)/lib/rustlib/$host/bin/llvm-ar"
if [ ! -x "$llvm_ar" ]; then
  echo "build-site: no llvm-ar at $llvm_ar — rustup component add llvm-tools" >&2
  exit 1
fi

AR_wasm32_unknown_unknown="$llvm_ar" \
  cargo build --release --locked -p prosody-wasm --target wasm32-unknown-unknown
cargo run --quiet --release --locked -p prosody-web -- --site "$dir"

target_dir=$(cargo metadata --format-version 1 --no-deps |
  grep -o '"target_directory":"[^"]*"' | cut -d'"' -f4)

# The bindings' generator must be exactly the version of the `wasm-bindgen` crate in Cargo.lock.
# It is installed beside the build rather than over whatever `wasm-bindgen` is on PATH, which other
# projects may need at another version.
version=$(sed -n '/^name = "wasm-bindgen"$/{n;s/^version = "\(.*\)"$/\1/p;}' Cargo.lock)
tools="$target_dir/tools"
bindgen="$tools/bin/wasm-bindgen"
if [ ! -x "$bindgen" ] || [ "$("$bindgen" --version)" != "wasm-bindgen $version" ]; then
  echo "build-site: installing wasm-bindgen-cli $version into $tools (once)" >&2
  cargo install --quiet --locked --root "$tools" wasm-bindgen-cli --version "$version"
fi
rm -f "$dir/prosody.wasm" # the name before the bindings were generated
"$bindgen" --target web --no-typescript --out-name prosody --out-dir "$dir" \
  "$target_dir/wasm32-unknown-unknown/release/prosody_wasm.wasm"
echo "build-site: $(wc -c < "$dir/prosody_bg.wasm" | tr -d ' ') bytes of prosody_bg.wasm in $dir"
